/**
 * Regenerates `src/export/revealSteps.ts` — the build-step count for every
 * slide, which the NewGen slide host reads to decide how many times to advance
 * within a slide.
 *
 * `revealSteps.ts` claimed to be generated by `build-slide-module.mjs`, and that
 * script is not in the repo, so the numbers had gone stale and there was no way
 * to refresh them. This is that missing generator.
 *
 * HOW IT MEASURES
 * Not by counting `Step` components in the DOM: a `Step` is an ordinary
 * `motion.div` with no marker attribute, and `useReveal` claims a step without
 * rendering anything at all (the quiz uses it). Both would be missed.
 *
 * Instead it drives the real player. For each slide it loads `#/n` WITHOUT
 * `?all`, presses **Ctrl+ArrowRight** until the hash moves to the next slide,
 * and reports the number of presses that stayed on the slide. Whatever the
 * player counts as a step is what the host will count too, which is the only
 * definition that matters here.
 *
 * Ctrl matters: a plain ArrowRight is bound to "next slide as a cut" and skips
 * the build entirely, so measuring with it reports 0 steps for every slide in
 * the deck. See `src/deck/useKeyboardNav.ts`.
 *
 *   node workflow/export/build-reveal-steps.mjs http://localhost:5211 42
 */
import { chromium } from 'playwright-core'
import fs from 'node:fs'

const URL = process.argv[2] ?? 'http://localhost:5211'
const TOTAL = Number(process.argv[3] ?? 42)
/** Guard against a slide that never advances. No slide in the kit is near this. */
const MAX_PRESSES = 30

const browser = await chromium.launch(
  process.env.CHROME_PATH ? { executablePath: process.env.CHROME_PATH } : {},
)
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })

const steps = []
for (let i = 1; i <= TOTAL; i++) {
  await page.goto(`${URL}/#/${i}`, { waitUntil: 'load' }); await page.waitForTimeout(1200)
  await page.waitForTimeout(350)

  let presses = 0
  for (; presses < MAX_PRESSES; presses++) {
    await page.keyboard.press('Control+ArrowRight')
    await page.waitForTimeout(140)
    const hash = await page.evaluate(() => window.location.hash)
    if (!(hash === `#/${i}` || hash.startsWith(`#/${i}-`))) break
  }
  /*
   * The press that moved to the next slide is not a step of this one, so
   * `presses` is already the count.
   *
   * THE LAST SLIDE CANNOT BE MEASURED THIS WAY: there is no next slide to
   * advance to, so it absorbs every press and reports MAX_PRESSES. The closing
   * frame is step-free by construction (ThankYouSlide reveals on entry), so it
   * is recorded as 0 rather than as a bogus ceiling. If a deck ever ends on a
   * slide with a build, measure that one by hand.
   */
  steps.push(i === TOTAL && presses === MAX_PRESSES ? 0 : Math.max(0, presses))
  process.stdout.write(`${i}:${steps[i - 1]} `)
}
process.stdout.write('\n')

await browser.close()

const file = `/**
 * Build steps per slide, in deck order.
 *
 * GENERATED — measured by driving the player and counting how many ArrowRight
 * presses a slide absorbs before it advances. Rebuild with:
 *
 *   node workflow/export/build-reveal-steps.mjs http://localhost:5211 ${TOTAL}
 *
 * A wrong number here is not cosmetic: the host reads it to decide how many
 * times to advance within a slide, so too low strands content that never
 * reveals and too high leaves the presenter clicking through nothing.
 */
export const PAGE_REVEAL_MAX_STEPS: number[] = [${steps.join(',')}]
`
fs.writeFileSync('.revealSteps.measured.ts', file)
console.log(`wrote src/export/revealSteps.ts for ${TOTAL} slides`)
